def normalize(s):
    if not s: return ''
    return re.sub(r'[\s　（）()ⅠⅡⅢⅣⅤⅥⅦⅧⅨⅩ]+', '', str(s)).lower()

def main():
    print("=" * 60)
    print("构建药品说明书数据库（新结构）")
    print("=" * 60)

    with open(os.path.join(BASE, 'drugs.json'), 'r', encoding='utf-8') as f:
        drugs = json.load(f)

    drug_by_norm = {}
    for d in drugs:
        dn = normalize(d.get('name', ''))
        if not dn: continue
        if dn not in drug_by_norm: drug_by_norm[dn] = []
        drug_by_norm[dn].append(d)

    matched = 0
    for info_name, info in DRUG_INFO.items():
        info['drug_name'] = info_name
        nn = normalize(info_name)
        if nn in drug_by_norm:
            for drug in drug_by_norm[nn]:
                drug['prescribing'] = info
                drug['essential'] = info.get('is_essential', False)
                matched += 1
        else:
            for dn, dlist in drug_by_norm.items():
                if nn in dn or dn in nn:
                    for drug in dlist:
                        drug['prescribing'] = info
                        drug['essential'] = info.get('is_essential', False)
                        matched += 1

    print(f"  {matched} 个药品关联了说明书")

    # Auto-generate insurance_notes from note field for drugs without prescribing
    note_audit_count = 0
    for d in drugs:
        note = d.get('note', '').strip()
        if note and not d.get('prescribing'):
            # Create a minimal prescribing entry with the note as insurance_notes
            d['prescribing'] = {
                'drug_name': d.get('name', ''),
                'insurance_notes': [
                    {'risk': 'high', 'text': f'【医保目录限定】{note}', 'materials': ['疾病诊断须符合医保限定支付适应症']}
                ]
            }
            note_audit_count += 1
        elif note and d.get('prescribing'):
            # Drug has prescribing but check if note is already in insurance_notes
            existing_notes = d['prescribing'].get('insurance_notes', [])
            note_already_added = any(note in n.get('text', '') for n in existing_notes)
            if not note_already_added and len(note) > 3:
                # Prepend the official limitation
                d['prescribing'].setdefault('insurance_notes', [])
                d['prescribing']['insurance_notes'].insert(0,
                    {'risk': 'high', 'text': f'【医保目录限定】{note}', 'materials': ['疾病诊断须符合医保限定支付适应症']})
                note_audit_count += 1
    print(f"  {note_audit_count} 药品通过note字段补充了医保审核规则")

    # Save
    drugs_path = os.path.join(BASE, 'drugs.json')
    with open(drugs_path, 'w', encoding='utf-8') as f:
        json.dump(drugs, f, ensure_ascii=False, indent=1)
    with open(drugs_path, 'rb') as f_in:
        with gzip.open(drugs_path + '.gz', 'wb', compresslevel=9) as f_out:
            f_out.write(f_in.read())

    with_info = sum(1 for d in drugs if d.get('prescribing'))
    with_essential = sum(1 for d in drugs if d.get('essential'))
    print(f"  {with_info}/{len(drugs)} 有说明书, {with_essential} 基药")

    print("\n✅ 完成")

if __name__ == '__main__':
    main()
